#!/usr/bin/env python3
"""Patch CURRENT filter_E2 train.py, train_flower.py, runner.py for E1_b-style metrics.
Run in filter_E2; backups created once. Idempotent and fail-closed on mismatches.
"""
from pathlib import Path
import py_compile
ROOT=Path(__file__).resolve().parent

def patch(name, modifications):
    f=ROOT/name
    if not f.exists(): raise SystemExit(f'Missing {f}')
    source=f.read_text()
    if '# E2_FULL_METRICS_V1' in source:
        print(name, 'already patched'); return
    original=source
    for before,after in modifications:
        occurrences=source.count(before)
        if occurrences != 1:
            raise SystemExit(f'{name}: expected one matching block, found {occurrences}: {before[:120]!r}. No changes saved.')
        source=source.replace(before,after,1)
    source='# E2_FULL_METRICS_V1\n'+source
    backup=f.with_suffix(f.suffix+'.before_e2_metrics')
    if not backup.exists(): backup.write_text(original)
    f.write_text(source)
    py_compile.compile(str(f),doraise=True)
    print('PATCHED',name)


